Only one root cause shows up: `ts-station-service` has a database-call failure. Its effect reaches the user through several call chains.

```json
{
  "root_causes": [
    {
      "service": "ts-station-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-station-service' AND span_name IN ('SELECT station','StationRepository.findByNames','POST /api/v1/stationservice/stations/idlist') GROUP BY ALL",
          "claim": "Station DB 'SELECT station' spans: 23 of 28 error with p95 about 30 s, the Hikari timeout, while the Server span fails the same way."
        },
        {
          "kind": "log",
          "sql": "SELECT level, left(message,120) msg, count(*) n FROM abnormal_logs WHERE service_name='ts-station-service' AND level IN ('ERROR','WARN') GROUP BY ALL ORDER BY n DESC",
          "claim": "Station logs 'Communications link failure' and 'HikariPool-1 - Connection is not available, request timed out after 30000ms' on the DB path."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),4) avg_v FROM abnormal_metrics WHERE attr_k8s_pod_name ILIKE 'mysql%' AND metric IN ('container.cpu.usage') GROUP BY ALL",
          "claim": "mysql-0 CPU fell to about 0.002 from 0.022 normal, so queries are not reaching the database; mysql itself is not saturated."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-station-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-basic-service' AND attr_span_kind IN ('Client','Server') GROUP BY ALL",
          "claim": "Basic-service client calls to station fail with about 30 s latency; its Server travel-query spans fail 22 of 26 times."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "Travel-service POST calls to basic-service fail 20 of 22 times with about 30 s p95; its own DB spans stay normal."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind IN ('Client','Server') GROUP BY ALL",
          "claim": "Route-plan calls to travel-service fail 12 of 30 times and its cheapest-route server spans fail 6 of 7."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind IN ('Client','Server') GROUP BY ALL",
          "claim": "Travel-plan calls to route-plan fail 12 of 21 times; its cheapest and quickest server spans fail with about 30 s latency."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Dashboard server p95 rose from about 76 ms to about 16 s; its travel-plan, travel and admin calls are failing or slow."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "Travel2-service calls to basic-service fail or stall, carrying the station fault up to the dashboard."
        }
      ]
    }
  ]
}
